css:
.deliverysim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #243b2f;
    background: linear-gradient(160deg, #f4f1e6 0%, #eaf1e8 100%);
    border-radius: 18px;
}

.deliverysim-container * {
    box-sizing: border-box;
}

.deliverysim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1f6f54 0%, #2e8b6a 50%, #4ca87c 100%);
    color: #f3fbf6;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(31, 111, 84, 0.30);
}

.deliverysim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.deliverysim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #fbe6b8;
    background: rgba(255, 255, 255, 0.14);
    padding: 5px 14px;
    border-radius: 999px;
}

.deliverysim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e2f3ea;
}

.deliverysim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c5b47;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.deliverysim-period-counter #currentDay,
.deliverysim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1f6f54;
}

.deliverysim-round-name {
    background: #d8eadf;
    color: #1f6f54;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.deliverysim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a5a14;
    background: #fbeccd;
    padding: 4px 12px;
    border-radius: 999px;
}

.deliverysim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.deliverysim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #dde7df;
    box-shadow: 0 4px 14px rgba(31, 111, 84, 0.06);
    border-top: 4px solid #2e8b6a;
}

.deliverysim-card-completion { border-top-color: #1f6f54; }
.deliverysim-card-effect { border-top-color: #2f6fb0; }
.deliverysim-card-engage { border-top-color: #b0712f; }
.deliverysim-card-cpo { border-top-color: #6a4fb0; }

.deliverysim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-weight: 700;
    color: #6a8475;
    line-height: 1.3;
}

.deliverysim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f6f54;
}

.deliverysim-card-completion .deliverysim-value { color: #1f6f54; }
.deliverysim-card-effect .deliverysim-value { color: #2f6fb0; }
.deliverysim-card-engage .deliverysim-value { color: #b0712f; }
.deliverysim-card-cpo .deliverysim-value { color: #6a4fb0; }

.deliverysim-sublabel {
    font-size: 0.75rem;
    color: #7d978a;
    line-height: 1.35;
}

.deliverysim-completion-fail .deliverysim-value { color: #c0392b; }
.deliverysim-completion-target .deliverysim-value { color: #1f6f54; }

.deliverysim-cpo-high .deliverysim-value { color: #c0392b; }
.deliverysim-cpo-low .deliverysim-value { color: #1f6f54; }

.deliverysim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1f6f54;
    color: #eef9f3;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.deliverysim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.deliverysim-budget-over #budgetDisplay {
    color: #ffd1c7;
}

.deliverysim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2e8b6a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(31, 111, 84, 0.05);
}

.deliverysim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.deliverysim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1f6f54;
    margin-bottom: 6px;
}

.deliverysim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #344f41;
}

.deliverysim-briefing-text strong { color: #1f6f54; }
.deliverysim-briefing-text em { color: #9a5a14; font-style: italic; }

.deliverysim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #dde7df;
    box-shadow: 0 4px 14px rgba(31, 111, 84, 0.06);
}

.deliverysim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f6f54;
    border-bottom: 2px solid #e7efe8;
    padding-bottom: 8px;
}

.deliverysim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c4a3b;
    margin: 14px 0 6px;
}

.deliverysim-container select,
.deliverysim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c2d6c9;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7fbf8;
    color: #243b2f;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.deliverysim-container select:focus,
.deliverysim-container input[type="number"]:focus {
    outline: none;
    border-color: #2e8b6a;
    box-shadow: 0 0 0 3px rgba(46, 139, 106, 0.16);
}

.deliverysim-container select option {
    background-color: #ffffff;
    color: #243b2f;
}

.deliverysim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2e8b6a;
}

.deliverysim-range-readout,
.deliverysim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2c5b47;
    margin-top: 4px;
}

.deliverysim-range-readout span:last-child,
.deliverysim-alloc-readout span:nth-child(2) {
    color: #1f6f54;
    font-weight: 800;
}

.deliverysim-hint {
    font-size: 0.8rem;
    color: #7d978a;
    margin-top: 4px;
    line-height: 1.4;
}

.deliverysim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.deliverysim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f3f9f5;
    border: 1px solid #dcebe0;
    border-radius: 9px;
    padding: 8px 12px;
}

.deliverysim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2c4a3b;
}

.deliverysim-alloc-row input[type="number"] {
    width: 92px;
    flex: 0 0 92px;
}

.deliverysim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.deliverysim-container .btn-primary {
    background: linear-gradient(135deg, #1f6f54 0%, #2e8b6a 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(31, 111, 84, 0.28);
}

.deliverysim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.deliverysim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c2d6c9;
    color: #6a8475;
}

.deliverysim-coach {
    background: #20413a;
    color: #eaf6ef;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(32, 65, 58, 0.22);
}

.deliverysim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8fd4b4;
    margin-bottom: 8px;
}

.deliverysim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.deliverysim-coach-body strong { color: #ffd98a; }
.deliverysim-coach-body em { color: #ffc1ad; font-style: italic; }

.deliverysim-history,
.deliverysim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #dde7df;
    box-shadow: 0 4px 14px rgba(31, 111, 84, 0.06);
}

.deliverysim-history h3,
.deliverysim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1f6f54;
}

.deliverysim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2c4a3b;
}

.deliverysim-container table#usfHistoryTable th {
    background: #e9f2eb;
    color: #1f6f54;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4e6da;
}

.deliverysim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef4f0;
}

.deliverysim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fbf9;
}

.deliverysim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .deliverysim-container {
        padding: 14px;
    }
    .deliverysim-header h1 {
        font-size: 1.7rem;
    }
    .deliverysim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .deliverysim-value {
        font-size: 1.9rem;
    }
    .deliverysim-clock {
        margin-left: 0;
    }
    .deliverysim-period-counter {
        font-size: 0.88rem;
    }
    .deliverysim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .deliverysim-alloc-row {
        flex-wrap: wrap;
    }
    .deliverysim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .deliverysim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.deliverysim-completion { padding: 8px 4px 4px; }
.deliverysim-cm-head { text-align: center; margin-bottom: 16px; }
.deliverysim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #1f6f54; }
.deliverysim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #5a7566; }
.deliverysim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #243b2f; }
.deliverysim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.deliverysim-cm-yes { background: rgba(31,111,84,0.15); color: #1a6049; border: 1px solid rgba(31,111,84,0.42); }
.deliverysim-cm-no { background: rgba(192,57,43,0.12); color: #c0392b; border: 1px solid rgba(192,57,43,0.4); }
.deliverysim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.deliverysim-cm-metric { flex: 1 1 120px; min-width: 108px; background: #f2f8f4; border: 1px solid #dde7df; border-radius: 10px; padding: 10px 8px; text-align: center; }
.deliverysim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #1f6f54; }
.deliverysim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5a7566; text-transform: uppercase; letter-spacing: 0.03em; }
.deliverysim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #243b2f; }
.deliverysim-cm-insights { margin: 0; padding-left: 20px; }
.deliverysim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #2c4a3b; }

