(function() {
    'use strict';

    class DeliveryAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Mode of Delivery`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_COMPLETION = 31;      // week-12 on-track completion
            this.TARGET_COMPLETION = 75;     // contractual target
            this.LEARNERS = 1200;            // dispersed shift supervisors
            this.BUDGET_CAP = 2.40;          // BRL 2.4M ceiling, in millions
            this.CONDITIONAL_EXTRA = 0.30;   // BRL 300k conditional (R4), in millions
            this.PROGRAM_HOURS = 40;         // notional learner-hours per supervisor for the redesign
            // Fully-loaded modality cost per learner-hour (BRL).
            this.RATE_ASYNC = 8;
            this.RATE_LIVE = 35;
            this.RATE_INPERSON = 120;
            // Scales the per-round effect/engage/completion deltas so a strong four-round path
            // approaches (rather than pegs) the 0–100 ceiling, preserving resolution for the
            // late-round levers (Round-4 pitch / curveballs). Tuned against the playthrough
            // traces: correct strategy ~ high-90s on all meters at R4; wrong strategies stay
            // measurably lower; the R4 cost-per-outcome pitch still shifts the final KPIs.
            this.DELTA_SCALE = 0.62;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    completion: this.START_COMPLETION,
                    effect: 34,
                    engage: 20,
                    programCost: 0,            // BRL millions, from the modality mix (set in R2)
                    engageSpend: 0,            // BRL millions, accountability investment (R3)
                    budgetUsed: 0,             // BRL millions, programCost + engageSpend (+ conditional buys)
                    budgetCap: this.BUDGET_CAP,
                    overBudget: false,
                    cpo: Math.round((this.START_COMPLETION / 100 * this.LEARNERS) > 0 ? (1.30 * 1000000) / (this.START_COMPLETION / 100 * this.LEARNERS) : 0),
                    tookConditional: false,
                    completionHistory: [this.START_COMPLETION],
                    effectHistory: [34],
                    engageHistory: [20],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    root: `design`,
                    signal: `week3`,
                    honesty: 60,
                    skillMode: `live`,
                    knowMode: `async`,
                    async: 55,
                    live: 35,
                    inperson: 10,
                    sequence: `flipped`,
                    schedule: `multi`,
                    engageBudget: 280,
                    protect: 60,
                    offer: `conditional`,
                    clash: `hybrid`,
                    pitch: `outcome`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const root = document.getElementById(`rootInput`);
                const signal = document.getElementById(`signalInput`);
                const hon = document.getElementById(`honestyInput`);
                if (root) decisions.root = root.value;
                if (signal) decisions.signal = signal.value;
                if (hon) decisions.honesty = parseInt(hon.value, 10);
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
            } else if (round === 2) {
                const sk = document.getElementById(`skillModeInput`);
                const kn = document.getElementById(`knowModeInput`);
                if (sk) decisions.skillMode = sk.value;
                if (kn) decisions.knowMode = kn.value;
                const a = document.getElementById(`asyncInput`);
                const l = document.getElementById(`liveInput`);
                const p = document.getElementById(`inpersonInput`);
                if (a) decisions.async = parseFloat(a.value);
                if (l) decisions.live = parseFloat(l.value);
                if (p) decisions.inperson = parseFloat(p.value);
                const parts = [decisions.async, decisions.live, decisions.inperson];
                if (parts.some((v) => !Number.isFinite(v) || v < 0 || v > 100)) {
                    warn(`warn_mix_range`); return false;
                }
                const total = Math.round(decisions.async + decisions.live + decisions.inperson);
                if (total !== 100) {
                    warn(`warn_mix_total`); return false;
                }
            } else if (round === 3) {
                const seq = document.getElementById(`sequenceInput`);
                const sch = document.getElementById(`scheduleInput`);
                const eb = document.getElementById(`engageInput`);
                const pr = document.getElementById(`protectInput`);
                if (seq) decisions.sequence = seq.value;
                if (sch) decisions.schedule = sch.value;
                if (eb) decisions.engageBudget = parseFloat(eb.value);
                if (pr) decisions.protect = parseInt(pr.value, 10);
                if (!Number.isFinite(decisions.engageBudget) || decisions.engageBudget < 0) {
                    warn(`warn_engage_negative`); return false;
                }
                if (!Number.isFinite(decisions.protect) || decisions.protect < 0 || decisions.protect > 100) {
                    warn(`warn_protect_range`); return false;
                }
            } else if (round === 4) {
                const of = document.getElementById(`offerInput`);
                const cl = document.getElementById(`clashInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (of) decisions.offer = of.value;
                if (cl) decisions.clash = cl.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // effectDelta = objective-modality fit / real learning; engageDelta = social glue;
            // paperDelta = coerced/forced completion not backed by fit or engagement (decays).
            let effectDelta = 0, engageDelta = 0, paperDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the design failure, not the learners (Common Error 1: learner-blaming).
                if (d.root === `design`) {
                    effectDelta += 14; engageDelta += 8; coachKey = `coach_r1_design`;
                } else if (d.root === `motivation`) {
                    effectDelta -= 10; engageDelta -= 6; coachKey = `coach_r1_motivation`;
                } else if (d.root === `content`) {
                    effectDelta -= 4; coachKey = `coach_r1_content`;
                } else {
                    effectDelta -= 4; engageDelta -= 2; coachKey = `coach_r1_platform`;
                }

                // Read the right analytics signal (week-3 drop-off + 82% live cohorts).
                if (d.signal === `week3`) {
                    effectDelta += 10; engageDelta += 6;
                    if (d.root === `design`) coachKey = `coach_r1_diag_sharp`;
                } else if (d.signal === `none`) {
                    effectDelta -= 8; coachKey = `coach_r1_none`;
                } else {
                    effectDelta -= 2;
                }

                // Honesty: owning the design vs blaming learners.
                if (d.honesty >= 60) { effectDelta += 6; engageDelta += 2; }
                else if (d.honesty <= 25) { effectDelta -= 8; coachKey = `coach_r1_lowhonesty`; }

                summaryKey = (d.root === `design` && d.signal === `week3`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Match objectives to modalities (Common Error 2: modality-by-cost; Error 3: overcorrection).
                // Skill & behaviour need synchronous/social; pure async for skill is the root error;
                // all in-person is the overcorrection that blows the ceiling.
                if (d.skillMode === `live`) {
                    effectDelta += 16; coachKey = `coach_r2_skilllive`;
                } else if (d.skillMode === `async`) {
                    effectDelta -= 12; paperDelta -= 4; coachKey = `coach_r2_skillasync`;
                } else { // inperson everywhere
                    effectDelta += 8; coachKey = `coach_r2_skillinperson`;
                }

                // Knowledge & compliance transfer well async — keeping them async is correct & cheap.
                if (d.knowMode === `async`) {
                    effectDelta += 8;
                } else if (d.knowMode === `live`) {
                    effectDelta -= 4; coachKey = `coach_r2_knowlive`;
                } else {
                    effectDelta -= 6; coachKey = `coach_r2_knowinperson`;
                }

                // Modality mix → notional program cost (BRL millions) for 1,200 learners.
                const hours = this.PROGRAM_HOURS;
                const blendedRate = (d.async / 100) * this.RATE_ASYNC
                    + (d.live / 100) * this.RATE_LIVE
                    + (d.inperson / 100) * this.RATE_INPERSON;
                ds.programCost = Math.round(blendedRate * hours * this.LEARNERS) / 1000000; // millions
                ds.programCost = Math.round(ds.programCost * 100) / 100;

                // A genuine blend: meaningful live, modest in-person, async backbone.
                const balancedBlend = d.live >= 25 && d.live <= 55 && d.inperson <= 20 && d.async >= 30;
                if (d.inperson >= 40 || ds.programCost > this.BUDGET_CAP) {
                    effectDelta += 4; engageDelta += 2; coachKey = `coach_r2_overcorrect`;
                } else if (balancedBlend && d.skillMode === `live` && d.knowMode === `async`) {
                    effectDelta += 10; engageDelta += 4; coachKey = `coach_r2_balanced`;
                } else if (d.async >= 75) {
                    effectDelta -= 8; coachKey = `coach_r2_stillasync`;
                }

                summaryKey = (d.skillMode === `live` && d.knowMode === `async` && ds.programCost <= this.BUDGET_CAP && d.inperson < 40) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Sequence + engagement (Common Error 4: accountability-free design).
                // Flipped model: async pre-work feeds live practice — each modality does its best.
                if (d.sequence === `flipped`) {
                    effectDelta += 12; engageDelta += 4; coachKey = `coach_r3_flipped`;
                } else if (d.sequence === `livefirst`) {
                    effectDelta -= 4; coachKey = `coach_r3_livefirst`;
                } else { // parallel
                    effectDelta -= 8; engageDelta -= 4; coachKey = `coach_r3_parallel`;
                }

                // Scheduling for a rotating-shift, 9-site workforce (Decision-tree: shift-clash).
                if (d.schedule === `multi`) {
                    engageDelta += 12; effectDelta += 4; coachKey = (d.sequence === `flipped`) ? `coach_r3_shiftfit` : coachKey;
                } else if (d.schedule === `fixed`) {
                    engageDelta -= 12; paperDelta += 4; coachKey = `coach_r3_fixedslot`;
                } else { // optional — no accountability
                    engageDelta -= 6; coachKey = `coach_r3_optional`;
                }

                // Engagement & accountability budget (R$k → millions added to spend).
                ds.engageSpend = Math.round((d.engageBudget / 1000) * 100) / 100;
                if (d.engageBudget >= 200) { engageDelta += 14; effectDelta += 4; }
                else if (d.engageBudget >= 80) { engageDelta += 6; effectDelta += 2; }
                else { engageDelta -= 8; coachKey = `coach_r3_noengage`; }

                // Protected learning time negotiated with the client.
                if (d.protect >= 60) { engageDelta += 8; effectDelta += 2; }
                else if (d.protect <= 25) { engageDelta -= 8; paperDelta += 4; coachKey = `coach_r3_noprotect`; }

                summaryKey = (d.sequence === `flipped` && d.schedule === `multi` && d.engageBudget >= 200) ? `sum_r3_good` : ((d.schedule === `fixed` || d.sequence === `parallel`) ? `sum_r3_paper` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend the blend & win the renewal (Common Error 5: cost-per-seat pitch).
                // Conditional BRL 300k: smart only with a credible plan to hit 70% + fallback.
                if (d.offer === `conditional`) {
                    effectDelta += 6; engageDelta += 6; ds.tookConditional = true; coachKey = `coach_r4_conditional`;
                } else if (d.offer === `grab`) {
                    paperDelta += 4; effectDelta -= 4; ds.tookConditional = true; coachKey = `coach_r4_grab`;
                } else { // decline
                    coachKey = `coach_r4_decline`;
                }

                // Shift-clash + lost facilitator solve.
                if (d.clash === `hybrid`) {
                    engageDelta += 12; effectDelta += 6; coachKey = (d.offer === `conditional`) ? `coach_r4_hybrid` : coachKey;
                } else if (d.clash === `cancel`) {
                    effectDelta -= 12; engageDelta -= 4; coachKey = `coach_r4_cancel`;
                } else { // force
                    engageDelta -= 12; paperDelta += 6; coachKey = `coach_r4_force`;
                }

                // The renewal pitch framing: cost per outcome, not cost per seat.
                if (d.pitch === `outcome`) {
                    effectDelta += 8; engageDelta += 4; coachKey = (d.clash === `hybrid` && d.offer === `conditional`) ? `coach_r4_outcome` : coachKey;
                } else if (d.pitch === `cheap`) {
                    effectDelta -= 8; paperDelta += 2; coachKey = `coach_r4_cheap`;
                } else { // effort
                    effectDelta -= 2; coachKey = `coach_r4_effort`;
                }

                // Conviction nudges effectiveness.
                effectDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.offer === `conditional` && d.clash === `hybrid` && d.pitch === `outcome`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Effectiveness & engagement move on their deltas. The deltas are sized for
            // pedagogical legibility (clear right/wrong gaps); DELTA_SCALE keeps a strong
            // four-round path from saturating the 0–100 meters before Round 4, so the late
            // levers (esp. the R4 cost-per-outcome pitch) still move the final KPIs and a
            // wrong final choice remains measurably penalised.
            const S = this.DELTA_SCALE;
            const sEffect = effectDelta * S;
            const sEngage = engageDelta * S;
            ds.effect = Math.max(0, Math.min(100, ds.effect + sEffect));
            ds.engage = Math.max(0, Math.min(100, ds.engage + sEngage));

            // Completion is driven by genuine effectiveness + engagement, plus any coerced/paper
            // gains. Paper gains lift the headline but are fragile and drag effectiveness.
            const realGain = (Math.max(0, sEffect) * 0.45) + (Math.max(0, sEngage) * 0.55);
            const paperGain = paperDelta * S * 0.9;
            const negDrag = (Math.min(0, sEffect) + Math.min(0, sEngage)) * 0.35;
            let completionDelta = realGain + paperGain + negDrag;
            ds.completion = Math.max(0, Math.min(100, ds.completion + completionDelta));

            // Budget accounting (BRL millions): program cost (set R2) + engagement spend (R3)
            // + conditional buy if taken in R4.
            let budget = (ds.programCost || 0) + (ds.engageSpend || 0);
            if (ds.tookConditional) budget = Math.max(0, budget - this.CONDITIONAL_EXTRA); // extra cash relaxes the net spend
            ds.budgetUsed = Math.round(budget * 100) / 100;
            ds.overBudget = (ds.programCost || 0) + (ds.engageSpend || 0) > this.BUDGET_CAP + 0.001;

            // Cost per completing learner (cost per outcome). Total deployed cost over learners
            // who actually complete. The async-cheap-low-completion trap surfaces here.
            const completers = Math.max(1, (ds.completion / 100) * this.LEARNERS);
            const totalCost = ((ds.programCost || 0) + (ds.engageSpend || 0)) * 1000000;
            ds.cpo = Math.round(totalCost / completers);

            // Flag paper completion: coercive levers pushed the headline while real
            // effectiveness lags it. Coercion (forced slots, fail-non-attendance, grabbing the
            // conditional cash, cost-per-seat framing) feeds paperDelta; if that produced a
            // headline meaningfully ahead of genuine learning, mark it as a fragile paper number.
            if (paperDelta >= 6 && ds.effect < ds.completion - 12) ds.paperCompletion = true;

            ds.completionHistory.push(Math.round(ds.completion));
            ds.effectHistory.push(Math.round(ds.effect));
            ds.engageHistory.push(Math.round(ds.engage));

            if (round === this.ROUNDS.length && ds.completion < this.TARGET_COMPLETION) ds.targetMissed = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite to the reporting/grading layer each period; final period locks the score.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                completion: Math.round(ds.completion),
                completionDelta: Math.round(completionDelta),
                effect: Math.round(ds.effect),
                effectDelta: Math.round(effectDelta),
                engage: Math.round(ds.engage),
                engageDelta: Math.round(engageDelta),
                cpo: ds.cpo,
                budgetUsed: ds.budgetUsed,
                overBudget: ds.overBudget,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtBRL(n) {
            // BRL formatting: thousands with '.', no decimals. e.g. 6452 -> R$6.452
            const v = Math.round(Number(n) || 0);
            return `R$` + v.toLocaleString(`pt-BR`);
        }

        _fmtMillions(n) {
            // BRL millions with comma decimal. e.g. 2.4 -> R$2,40M
            const v = (Number(n) || 0).toFixed(2).replace(`.`, `,`);
            return `R$` + v + `M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`completionDisplay`, `domainState.completion`, (v) => {
                const card = document.querySelector(`.deliverysim-card-completion`);
                if (card) {
                    card.classList.toggle(`deliverysim-completion-target`, Number(v) >= this.TARGET_COMPLETION);
                    card.classList.toggle(`deliverysim-completion-fail`, Number(v) < this.TARGET_COMPLETION);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`effectDisplay`, `domainState.effect`, (v) => Math.round(v));
            uiManager.bind(`engageDisplay`, `domainState.engage`, (v) => Math.round(v));
            const self = this;
            uiManager.bind(`cpoDisplay`, `domainState.cpo`, (v) => {
                const card = document.querySelector(`.deliverysim-card-cpo`);
                if (card) {
                    card.classList.toggle(`deliverysim-cpo-low`, Number(v) > 0 && Number(v) <= 3500);
                    card.classList.toggle(`deliverysim-cpo-high`, Number(v) > 6000);
                }
                return self._fmtBRL(v);
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const bar = document.querySelector(`.deliverysim-budget-bar`);
                if (bar) bar.classList.toggle(`deliverysim-budget-over`, Number(v) > self.BUDGET_CAP + 0.001);
                return self._fmtMillions(v) + ` / ` + self._fmtMillions(self.BUDGET_CAP);
            });

            // Honesty slider readout.
            const hon = document.getElementById(`honestyInput`);
            const honReadout = document.getElementById(`honestyReadout`);
            if (hon && honReadout) {
                honReadout.textContent = hon.value;
                hon.addEventListener(`input`, function() { honReadout.textContent = hon.value; });
            }

            // Protect slider readout.
            const pr = document.getElementById(`protectInput`);
            const prReadout = document.getElementById(`protectReadout`);
            if (pr && prReadout) {
                prReadout.textContent = pr.value;
                pr.addEventListener(`input`, function() { prReadout.textContent = pr.value; });
            }

            // Modality-mix live total (must hit 100%).
            const mixIds = [`asyncInput`, `liveInput`, `inpersonInput`];
            const mixReadout = document.getElementById(`mixReadout`);
            const recompute = function() {
                let total = 0;
                mixIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (mixReadout) mixReadout.textContent = total;
                const readoutEl = document.querySelector(`.deliverysim-alloc-readout`);
                if (readoutEl) readoutEl.style.color = (total !== 100) ? `#c0392b` : ``;
            };
            mixIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        // Localized chart label with a safe English fallback (chart is built once at load).
        _cl(key, fallback) {
            const v = (window.mySimulation && typeof window.mySimulation.t === `function`) ? window.mySimulation.t(key) : key;
            return (v && v !== key) ? v : fallback;
        }

        getChartConfig() {
            return {
                deliveryChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._cl(`legend_completion`, `Projected Completion %`),
                                data: [],
                                borderColor: `#1f6f54`,
                                backgroundColor: `rgba(31,111,84,0.14)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#1f6f54`,
                                yAxisID: `y`
                            },
