                                label: this._cl(`legend_effect`, `Learning Effectiveness`),
                                data: [],
                                borderColor: `#2f6fb0`,
                                backgroundColor: `rgba(47,111,176,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
