                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#6a8475` }, grid: { color: `rgba(31,111,84,0.08)` },
                                title: { display: true, text: `0–100 / %`, color: `#6a8475` }
                            },
                            x: {
                                ticks: { color: `#6a8475` }, grid: { color: `rgba(31,111,84,0.06)` },
                                title: { display: true, text: `Round`, color: `#6a8475` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.completionHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                deliveryChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.completionHistory },
                        { data: ds.effectHistory },
                        { data: ds.engageHistory }
                    ]
                }
            };
        }

        // Shared composite (0-100). Written to domainState.performance.overallScore each period for
        // the reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const completion = Math.round(ds.completion || 0);
            const effect = Math.round(ds.effect || 0);
            const engage = Math.round(ds.engage || 0);
            const composite = Math.round(Math.min(100, completion) * 0.35 + effect * 0.33 + engage * 0.32);
            return Math.max(0, Math.min(100, composite));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const completion = Math.round(ds.completion);
            const effect = Math.round(ds.effect);
            const engage = Math.round(ds.engage);
            const cpo = ds.cpo;

            const hitTarget = completion >= this.TARGET_COMPLETION;
            const realBlend = effect >= 60 && engage >= 55;
            const paper = ds.paperCompletion || (hitTarget && effect < 45);
            const onBudget = !ds.overBudget;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            let performanceKey = `grade_stalled`;
            if (hitTarget && realBlend && onBudget && composite >= 72) performanceKey = `grade_won`;
            else if (hitTarget && realBlend && onBudget) performanceKey = `grade_credible`;
            else if (hitTarget && !onBudget) performanceKey = `grade_overbudget`;
            else if (hitTarget && paper) performanceKey = `grade_paper`;
            else if (hitTarget) performanceKey = `grade_thin`;
            else if (completion > this.START_COMPLETION + 18) performanceKey = `grade_improving`;
            const performance = T(performanceKey);

            const insights = [];
            if (hitTarget && realBlend && onBudget) insights.push(window.mySimulation.t(`insight_won`));
            else if (hitTarget && !onBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            else if (hitTarget && paper) insights.push(window.mySimulation.t(`insight_paper`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_thin`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (engage < 45) insights.push(window.mySimulation.t(`insight_engage`));
            if (effect < 45) insights.push(window.mySimulation.t(`insight_loweffect`));
            if (cpo > 6000) insights.push(window.mySimulation.t(`insight_highcpo`));
            if (hitTarget && realBlend && cpo > 0 && cpo <= 3500) insights.push(window.mySimulation.t(`insight_lowcpo`));

            return {
                completion: completion,
                effect: effect,
                engage: engage,
                cpo: cpo,
                cpoLabel: this._fmtBRL(cpo),
                hitTarget: hitTarget,
                realBlend: realBlend,
                paper: paper,
                onBudget: onBudget,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        // v1.1.0: render the computed grade, KPIs and insight debrief in the completion modal
        // instead of the framework generic "you completed N periods" fallback.
        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!(s.hitTarget && s.realBlend && s.onBudget);
            const badge = met
                ? `<span class="deliverysim-cm-badge deliverysim-cm-yes">` + T(`cm_won`) + `</span>`
                : `<span class="deliverysim-cm-badge deliverysim-cm-no">` + T(`cm_notwon`) + `</span>`;
            const budgetBadge = (s.onBudget === false)
                ? ` <span class="deliverysim-cm-badge deliverysim-cm-no">` + T(`cm_overbudget`) + `</span>`
                : ``;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const cpoText = (s.cpoLabel != null) ? s.cpoLabel : String(Math.round(s.cpo || 0));
            const metrics = ``
                + `<div class="deliverysim-cm-metric"><span class="deliverysim-cm-mv">` + Math.round(s.completion || 0) + `%</span><span class="deliverysim-cm-ml">` + T(`cm_m_completion`) + `</span></div>`
                + `<div class="deliverysim-cm-metric"><span class="deliverysim-cm-mv">` + Math.round(s.effect || 0) + `</span><span class="deliverysim-cm-ml">` + T(`cm_m_effect`) + `</span></div>`
                + `<div class="deliverysim-cm-metric"><span class="deliverysim-cm-mv">` + Math.round(s.engage || 0) + `</span><span class="deliverysim-cm-ml">` + T(`cm_m_engage`) + `</span></div>`
                + `<div class="deliverysim-cm-metric"><span class="deliverysim-cm-mv">` + cpoText + `</span><span class="deliverysim-cm-ml">` + T(`cm_m_cpo`) + `</span></div>`;
            return ``
                + `<div class="deliverysim-completion">`
                +   `<div class="deliverysim-cm-head">`
                +     `<div class="deliverysim-cm-score">` + score + `<span class="deliverysim-cm-score-max">/100</span></div>`
                +     `<div class="deliverysim-cm-grade">` + grade + ` ` + badge + budgetBadge + `</div>`
                +   `</div>`
                +   `<div class="deliverysim-cm-metrics">` + metrics + `</div>`
                +   `<div class="deliverysim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="deliverysim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overBudget) return window.mySimulation.t(`hint_overbudget`);
            if (ds.paperCompletion) return window.mySimulation.t(`hint_paper`);
            if (ds.engage < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_engage`);
            if (ds.effect < 35) return window.mySimulation.t(`hint_effect`);
            if (state.currentPeriod >= 3 && ds.completion < 55) return window.mySimulation.t(`hint_behind`);
            if (ds.completion >= this.TARGET_COMPLETION && ds.effect >= 60 && ds.engage >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.completion`, label: `Completion`, i18nKey: `col_completion`, formatter: (v) => Math.round(v) + `%` },
                { key: `results.effect`, label: `Effectiveness`, i18nKey: `col_effect`, formatter: (v) => Math.round(v) },
                { key: `results.cpo`, label: `Cost/Outcome`, i18nKey: `col_cpo`, formatter: (v) => self._fmtBRL(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
                    title:                  `Mode of Delivery`,
                    subtitle:               `A flagship 16-week program for 1,200 shift-based supervisors was built 80% self-paced to control cost — and it is failing at 31% completion against a 75% target. The CHRO is about to decide a BRL 9M renewal. You have a hard BRL 2.4M ceiling and four rounds to rebuild the blend, lift completion and effectiveness, and win the account on cost per outcome — not cost per seat.`,
                    header_tag:             `11 May 2026 · Travessia Soluções Educacionais · Belo Horizonte · Frontline Leadership in crisis`,
                    round_label:            `Round`,
                    period_of:              `of`,
                    decisions_heading:      `Your Decisions This Round`,
